def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    feature = next(x for x in counts if x != bg)
    h, w = len(grid), len(grid[0])
    for i in range(h):
        js = [j for j in range(w) if grid[i][j] == feature]
        for a, b in zip(js, js[1:]):
            if 1 <= b - a - 1 <= 4:
                for j in range(a + 1, b):
                    if grid[i][j] == bg: out[i][j] = 2
    for j in range(w):
        ii = [i for i in range(h) if grid[i][j] == feature]
        for a, b in zip(ii, ii[1:]):
            if 1 <= b - a - 1 <= 4:
                for i in range(a + 1, b):
                    if grid[i][j] == bg: out[i][j] = 2
    return out
